// Push handlers for Nothing BOT Comedy. Pulled into the app's one service worker (generated by vite-plugin-pwa) with Workbox
// importScripts, so there is a single worker at this site's root scope (the comic site is its own origin, apart from Curating).
// The server sends data-only FCM messages: { kind, title, body, link, alertId } (apps/worker/src/notify.ts, notifyComic).
// A spot alert carries an "Ask for it" action: it opens the app on that alert with the ask ready to send (one tap).

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = { data: { body: event.data ? event.data.text() : "" } };
  }
  const n = payload.notification || {};
  const d = payload.data || {};
  const title = d.title || n.title || "Nothing BOT Comedy";
  const body = d.body || n.body || "";
  const link = d.link || (payload.fcmOptions && payload.fcmOptions.link) || "/alerts";
  const isSpot = d.kind === "spot_alert";

  event.waitUntil(
    (async () => {
      const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const visible = wins.filter((w) => w.visibilityState === "visible");
      if (visible.length) {
        // The app is on screen: it shows a toast instead of a system notification.
        visible.forEach((w) => w.postMessage({ type: "nbc-push", kind: d.kind, title, body, link, alertId: d.alertId }));
        return;
      }
      await self.registration.showNotification(title, {
        body,
        icon: "/icons/nbc/icon-192.png",
        badge: "/icons/nbc/icon-96.png",
        tag: d.alertId || d.kind || "nbc",
        // Stays until you act on it: an offer is only good for a short while.
        requireInteraction: isSpot,
        timestamp: Date.now(),
        data: { link, kind: d.kind, alertId: d.alertId },
        actions: isSpot ? [{ action: "ask", title: "Ask for it" }] : [],
      });
    })(),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const data = event.notification.data || {};
  // Always land on this origin (the link in the message is the production URL; dev and previews differ).
  const u = new URL(data.link || "/alerts", self.location.origin);
  if (event.action === "ask") u.searchParams.set("ask", "1");
  const target = self.location.origin + u.pathname + u.search + u.hash;
  event.waitUntil(
    (async () => {
      const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const win = wins[0];
      if (win) {
        try {
          await win.focus();
          await win.navigate(target);
          return;
        } catch {
          /* fall through and open a new window */
        }
      }
      await self.clients.openWindow(target);
    })(),
  );
});
